CREATE TABLE workflow_release_snapshot_sets (
  instance_id TEXT NOT NULL PRIMARY KEY REFERENCES workflow_runs (instance_id) ON DELETE CASCADE
)

CREATE TABLE scan_quarantine_exclusions (
  scan_id TEXT PRIMARY KEY REFERENCES scans (id) ON DELETE CASCADE
)

CREATE TRIGGER scanner_setups_mode AFTER UPDATE OF mode ON scanners BEGIN
  UPDATE scanner_setups SET mode=NEW.mode WHERE scanner_id=NEW.id;
END

CREATE TRIGGER scanner_setups_revoked AFTER UPDATE OF revoked_at ON scanners WHEN NEW.revoked_at IS NOT NULL BEGIN
  UPDATE scanner_setups SET admin_user_id=NULL WHERE scanner_id=NEW.id;
END

CREATE TRIGGER org_memberships_no_replace BEFORE INSERT ON org_memberships
BEGIN
  SELECT CASE WHEN EXISTS (SELECT 1 FROM org_memberships WHERE id = NEW.id)
    THEN RAISE(ABORT, 'UNIQUE constraint failed: org_memberships.id') END;
  SELECT CASE WHEN EXISTS (SELECT 1 FROM org_memberships WHERE invitation_id = NEW.invitation_id)
    THEN RAISE(ABORT, 'UNIQUE constraint failed: org_memberships.invitation_id') END;
  SELECT CASE WHEN NEW.revoked_at IS NULL AND EXISTS (SELECT 1 FROM org_memberships
      WHERE org_id = NEW.org_id AND user_id = NEW.user_id AND revoked_at IS NULL)
    THEN RAISE(ABORT, 'UNIQUE constraint failed: org_memberships.org_id, org_memberships.user_id') END;
END

CREATE TRIGGER signing_identity_revision_insert AFTER INSERT ON signing_identities
BEGIN
  UPDATE signing_identity_revision_sequence SET revision = revision + 1 WHERE id = 1;
  UPDATE signing_identities SET revision = (SELECT revision FROM signing_identity_revision_sequence WHERE id = 1)
    WHERE id = NEW.id;
END

CREATE TRIGGER api_keys_no_replace BEFORE INSERT ON api_keys
BEGIN
  SELECT CASE WHEN EXISTS (SELECT 1 FROM api_keys WHERE id = NEW.id)
    THEN RAISE(ABORT, 'UNIQUE constraint failed: api_keys.id') END;
  SELECT CASE WHEN EXISTS (SELECT 1 FROM api_keys WHERE prefix = NEW.prefix)
    THEN RAISE(ABORT, 'UNIQUE constraint failed: api_keys.prefix') END;
  SELECT CASE WHEN EXISTS (SELECT 1 FROM api_keys WHERE key_hash = NEW.key_hash)
    THEN RAISE(ABORT, 'UNIQUE constraint failed: api_keys.key_hash') END;
END

CREATE TRIGGER scan_retention_event_changed AFTER UPDATE ON pass_events
BEGIN
  UPDATE scan_retention_proofs SET invalidated = 1 WHERE invalidated = 0 AND (
    ledger_event_id = OLD.id OR EXISTS (SELECT 1 FROM scans s WHERE s.id=scan_retention_proofs.scan_id AND (
      (s.pass_id=OLD.pass_id AND s.org_id=OLD.org_id AND s.mode=OLD.mode AND s.id=(CASE WHEN json_valid(OLD.data) THEN json_extract(OLD.data,'$.scanId') END))
      OR (s.pass_id=NEW.pass_id AND s.org_id=NEW.org_id AND s.mode=NEW.mode AND s.id=(CASE WHEN json_valid(NEW.data) THEN json_extract(NEW.data,'$.scanId') END))
    ))
  );
END

CREATE TRIGGER pass_credential_no_replace_insert BEFORE INSERT ON passes
BEGIN
  SELECT CASE WHEN EXISTS (SELECT 1 FROM passes p WHERE p.id = NEW.id)
    THEN RAISE(ABORT, 'UNIQUE constraint failed: passes.id') END;
  SELECT CASE WHEN EXISTS (SELECT 1 FROM passes p WHERE p.download_token = NEW.download_token)
    THEN RAISE(ABORT, 'UNIQUE constraint failed: passes.download_token') END;
  SELECT CASE WHEN EXISTS (SELECT 1 FROM passes p WHERE p.identity_id = NEW.identity_id AND p.serial = NEW.serial)
    THEN RAISE(ABORT, 'UNIQUE constraint failed: passes.identity_id, passes.serial') END;
  SELECT CASE WHEN NEW.scan_code IS NOT NULL AND EXISTS (SELECT 1 FROM passes p WHERE p.scan_code = NEW.scan_code)
    THEN RAISE(ABORT, 'UNIQUE constraint failed: passes.scan_code') END;
  SELECT CASE WHEN NEW.connection_id IS NOT NULL AND NEW.external_ref IS NOT NULL
    AND EXISTS (SELECT 1 FROM passes p WHERE p.org_id = NEW.org_id AND p.connection_id = NEW.connection_id
      AND p.external_ref = NEW.external_ref)
    THEN RAISE(ABORT, 'UNIQUE constraint failed: passes.org_id, passes.connection_id, passes.external_ref') END;
END

CREATE TRIGGER passes_deleted_drops_seals AFTER UPDATE OF deleted_at ON passes
WHEN OLD.deleted_at IS NULL AND NEW.deleted_at IS NOT NULL
BEGIN
  DELETE FROM pass_auth_seals WHERE pass_id = NEW.id;
  DELETE FROM pass_token_seals WHERE pass_id = NEW.id;
END

CREATE TRIGGER tag_bindings_insert_check BEFORE INSERT ON tag_bindings
BEGIN
  SELECT RAISE(ABORT, 'tag_binding_ended') WHERE NEW.ended_at IS NOT NULL;
  SELECT RAISE(ABORT, 'tag_retired') WHERE EXISTS (SELECT 1 FROM nfc_tags t WHERE t.id = NEW.tag_id AND t.status <> 'active');
  SELECT RAISE(ABORT, 'tag_lost') WHERE EXISTS (SELECT 1 FROM nfc_tags t WHERE t.id = NEW.tag_id AND t.lost_at IS NOT NULL);
  SELECT RAISE(ABORT, 'tag_binding_tenant') WHERE NOT EXISTS (
    SELECT 1 FROM nfc_tags t JOIN passes p ON p.org_id = t.org_id AND p.mode = t.mode
    WHERE t.id = NEW.tag_id AND p.id = NEW.pass_id AND p.deleted_at IS NULL);
  SELECT RAISE(ABORT, 'tag_binding_owner') WHERE NEW.scope = 'user'
    AND NOT EXISTS (SELECT 1 FROM passes p WHERE p.id = NEW.pass_id AND p.owner_user_id = NEW.user_id);
  SELECT RAISE(ABORT, 'tag_binding_limit') WHERE NEW.scope = 'pass'
    AND (SELECT count(*) FROM tag_bindings b WHERE b.pass_id = NEW.pass_id AND b.scope = 'pass' AND b.ended_at IS NULL) >= 4;
  SELECT RAISE(ABORT, 'tag_binding_limit') WHERE NEW.scope = 'user'
    AND (SELECT count(*) FROM tag_bindings b JOIN nfc_tags bt ON bt.id = b.tag_id JOIN nfc_tags nt ON nt.id = NEW.tag_id
      WHERE b.user_id = NEW.user_id AND b.scope = 'user' AND b.ended_at IS NULL
        AND bt.org_id = nt.org_id AND bt.mode = nt.mode) >= 4;
END

CREATE TRIGGER tag_enrollments_insert_check BEFORE INSERT ON tag_enrollments
BEGIN
  SELECT RAISE(ABORT, 'enrollment_pending') WHERE NEW.state <> 'pending';
  SELECT RAISE(ABORT, 'enrollment_tenant') WHERE NOT EXISTS (
    SELECT 1 FROM passes p JOIN scanners s ON s.org_id = p.org_id AND s.mode = p.mode
    WHERE p.id = NEW.pass_id AND s.id = NEW.scanner_id AND p.org_id = NEW.org_id AND p.mode = NEW.mode
      AND p.deleted_at IS NULL AND s.revoked_at IS NULL AND s.device_role = 'scan' AND s.kind = 'device');
  SELECT RAISE(ABORT, 'enrollment_owner') WHERE NEW.scope = 'user'
    AND NOT EXISTS (SELECT 1 FROM passes p WHERE p.id = NEW.pass_id AND p.owner_user_id = NEW.user_id);
END

CREATE TRIGGER nfc_tags_type_insert BEFORE INSERT ON nfc_tags WHEN NEW.type_id IS NOT NULL
BEGIN
  SELECT RAISE(ABORT, 'tag_type_tenant') WHERE NOT EXISTS (
    SELECT 1 FROM nfc_tag_types y WHERE y.id = NEW.type_id AND y.org_id = NEW.org_id);
  SELECT RAISE(ABORT, 'tag_type_system') WHERE EXISTS (
    SELECT 1 FROM nfc_tag_types y WHERE y.id = NEW.type_id AND y.system <> NEW.system);
  SELECT RAISE(ABORT, 'tag_type_archived') WHERE EXISTS (
    SELECT 1 FROM nfc_tag_types y WHERE y.id = NEW.type_id AND y.archived_at IS NOT NULL);
END

CREATE TRIGGER nfc_tags_type_update BEFORE UPDATE OF type_id ON nfc_tags
WHEN NEW.type_id IS NOT NULL AND NEW.type_id IS NOT OLD.type_id
BEGIN
  SELECT RAISE(ABORT, 'tag_type_tenant') WHERE NOT EXISTS (
    SELECT 1 FROM nfc_tag_types y WHERE y.id = NEW.type_id AND y.org_id = NEW.org_id);
  SELECT RAISE(ABORT, 'tag_type_system') WHERE EXISTS (
    SELECT 1 FROM nfc_tag_types y WHERE y.id = NEW.type_id AND y.system <> NEW.system);
  SELECT RAISE(ABORT, 'tag_type_archived') WHERE EXISTS (
    SELECT 1 FROM nfc_tag_types y WHERE y.id = NEW.type_id AND y.archived_at IS NOT NULL);
END

CREATE TRIGGER nfc_tag_keysets_update BEFORE UPDATE ON nfc_tag_keysets
BEGIN
  SELECT RAISE(ABORT, 'keyset_disabled') WHERE OLD.disabled_at IS NOT NULL AND NEW.disabled_at IS NOT OLD.disabled_at;
  SELECT RAISE(ABORT, 'keyset_type_tenant') WHERE NEW.type_id IS NOT NULL AND NEW.type_id IS NOT OLD.type_id
    AND NOT EXISTS (SELECT 1 FROM nfc_tag_types y WHERE y.id = NEW.type_id AND y.org_id = NEW.org_id AND y.system = 'sun');
END

CREATE TRIGGER nfc_tag_keys_insert BEFORE INSERT ON nfc_tag_keys
BEGIN
  SELECT RAISE(ABORT, 'tag_key_state') WHERE NEW.state <> 'active';
  SELECT RAISE(ABORT, 'keyset_disabled') WHERE EXISTS (
    SELECT 1 FROM nfc_tag_keysets k WHERE k.id = NEW.keyset_id AND k.disabled_at IS NOT NULL);
  SELECT RAISE(ABORT, 'tag_key_version') WHERE NEW.version <>
    coalesce((SELECT max(version) FROM nfc_tag_keys k WHERE k.keyset_id = NEW.keyset_id), 0) + 1;
END

CREATE TRIGGER nfc_tag_keysets_insert BEFORE INSERT ON nfc_tag_keysets
BEGIN
  SELECT RAISE(ABORT, 'keyset_disabled') WHERE NEW.disabled_at IS NOT NULL;
  SELECT RAISE(ABORT, 'keyset_limit') WHERE (SELECT count(*) FROM nfc_tag_keysets k
    WHERE k.org_id = NEW.org_id AND k.mode = NEW.mode AND k.disabled_at IS NULL) >= 4;
  SELECT RAISE(ABORT, 'keyset_per_tag') WHERE NEW.per_tag = 1 AND NEW.diversify = 1;
  SELECT RAISE(ABORT, 'keyset_type_tenant') WHERE NEW.type_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM nfc_tag_types y WHERE y.id = NEW.type_id AND y.org_id = NEW.org_id AND y.system = 'sun');
END

CREATE TRIGGER nfc_tag_sun_insert BEFORE INSERT ON nfc_tag_sun
BEGIN
  SELECT RAISE(ABORT, 'tag_sun_tenant') WHERE NOT EXISTS (
    SELECT 1 FROM nfc_tags t JOIN nfc_tag_keysets k ON k.org_id = t.org_id AND k.mode = t.mode
    WHERE t.id = NEW.tag_id AND t.system = 'sun' AND k.id = NEW.keyset_id);
  SELECT RAISE(ABORT, 'keyset_disabled') WHERE EXISTS (
    SELECT 1 FROM nfc_tag_keysets k WHERE k.id = NEW.keyset_id AND k.disabled_at IS NOT NULL);
  SELECT RAISE(ABORT, 'tag_key_state') WHERE NOT EXISTS (
    SELECT 1 FROM nfc_tag_keys y WHERE y.keyset_id = NEW.keyset_id AND y.version = NEW.key_version
      AND y.state = 'active');
  SELECT RAISE(ABORT, 'tag_sun_own_key') WHERE (NEW.kek_version IS NOT NULL) <>
    (SELECT k.per_tag FROM nfc_tag_keysets k WHERE k.id = NEW.keyset_id);
END

CREATE TRIGGER pass_boundaries_stamp AFTER UPDATE OF stamped_at ON pass_boundaries
WHEN NEW.stamped_at > OLD.stamped_at
BEGIN
  INSERT INTO revisions (pass_id, at) VALUES (NEW.pass_id, NEW.stamped_at);
  UPDATE pass_boundaries SET stamp = last_insert_rowid() WHERE pass_id = NEW.pass_id;
END
